1	<!DOCTYPE html>
2	<html lang="en">
3	<head>
4	<meta charset="utf-8">
5	<meta name="viewport" content="width=device-width, initial-scale=1">
6	<title>Calculator</title>
7	<style>
8	  * { box-sizing: border-box; }
9	  body {
10	    margin: 0;
11	    min-height: 100vh;
12	    display: flex;
13	    align-items: center;
14	    justify-content: center;
15	    background: #eceef1;
16	    font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, Helvetica, Arial, sans-serif;
17	  }
18	  .calc {
19	    position: relative;
20	    width: 320px;
21	    max-width: calc(100vw - 32px);
22	    padding: 16px;
23	    background: #1f2328;
24	    border-radius: 20px;
25	    box-shadow: 0 12px 32px rgba(0, 0, 0, 0.25);
26	  }
27	  .display {
28	    height: 88px;
29	    padding: 0 12px;
30	    margin-bottom: 16px;
31	    display: flex;
32	    align-items: flex-end;
33	    justify-content: flex-end;
34	    color: #fff;
35	    font-size: 48px;
36	    font-weight: 300;
37	    white-space: nowrap;
38	    overflow: hidden;
39	    font-variant-numeric: tabular-nums;
40	  }
41	  .groups {
42	    position: absolute;
43	    top: 22px;
44	    left: 28px;
45	    color: #9aa0a6;
46	    font-size: 18px;
47	    letter-spacing: 2px;
48	  }
49	  .display.small { font-size: 32px; }
50	  .display.tiny { font-size: 22px; }
51	  .keys {
52	    display: grid;
53	    grid-template-columns: repeat(4, 1fr);
54	    gap: 10px;
55	  }
56	  button {
57	    height: 64px;
58	    border: 0;
59	    border-radius: 14px;
60	    font: inherit;
61	    font-size: 24px;
62	    color: #fff;
63	    background: #3a4048;
64	    cursor: pointer;
65	    user-select: none;
66	  }
67	  button:hover { filter: brightness(1.12); }
68	  button:active { filter: brightness(0.9); }
69	  button:focus-visible { outline: 2px solid #8ab4f8; outline-offset: 2px; }
70	  .op { background: #f59e0b; }
71	  .op.active { background: #fff; color: #f59e0b; }
72	  .fn { background: #9aa0a6; color: #111; }
73	  .wide { grid-column: span 2; }
74	</style>
75	</head>
76	<body>
77	<div class="calc">
78	  <div class="display" data-testid="calc-display" data-value="0" data-error="false" role="status" aria-live="polite">0</div>
79	  <div class="groups" data-testid="calc-groups" aria-hidden="true"></div>
80	  <div class="keys">
81	    <button class="fn wide" data-testid="key-lparen" data-action="lparen" aria-label="open group">(</button>
82	    <button class="fn wide" data-testid="key-rparen" data-action="rparen" aria-label="close group">)</button>
83	
84	    <button class="fn" data-testid="key-clear" data-action="clear">AC</button>
85	    <button class="fn" data-testid="key-sign" data-action="sign" aria-label="change sign">±</button>
86	    <button class="fn" data-testid="key-percent" data-action="percent" aria-label="percent">%</button>
87	    <button class="op" data-testid="key-div" data-op="/" aria-label="divide">÷</button>
88	
89	    <button data-testid="key-7" data-digit="7">7</button>
90	    <button data-testid="key-8" data-digit="8">8</button>
91	    <button data-testid="key-9" data-digit="9">9</button>
92	    <button class="op" data-testid="key-mul" data-op="*" aria-label="multiply">×</button>
93	
94	    <button data-testid="key-4" data-digit="4">4</button>
95	    <button data-testid="key-5" data-digit="5">5</button>
96	    <button data-testid="key-6" data-digit="6">6</button>
97	    <button class="op" data-testid="key-sub" data-op="-" aria-label="subtract">−</button>
98	
99	    <button data-testid="key-1" data-digit="1">1</button>
100	    <button data-testid="key-2" data-digit="2">2</button>
101	    <button data-testid="key-3" data-digit="3">3</button>
102	    <button class="op" data-testid="key-add" data-op="+" aria-label="add">+</button>
103	
104	    <button class="wide" data-testid="key-0" data-digit="0">0</button>
105	    <button data-testid="key-dot" data-action="dot" aria-label="decimal point">.</button>
106	    <button class="op" data-testid="key-equals" data-action="equals" aria-label="equals">=</button>
107	  </div>
108	</div>
109	<script>
110	(function () {
111	  var display = document.querySelector('[data-testid="calc-display"]');
112	  var groupsEl = document.querySelector('[data-testid="calc-groups"]');
113	  var opButtons = document.querySelectorAll('[data-op]');
114	
115	  var state;
116	
117	  function reset() {
118	    state = {
119	      entry: '0',        // text of the number being typed
120	      value: 0,          // exact current value when not typing; never rounded
121	      stored: null,      // left operand
122	      op: null,          // pending operator
123	      typing: false,     // true while the user is building an entry
124	      edited: false,     // true when ± or % turned the display into the entry
125	      lastOp: null,      // for repeated equals
126	      lastOperand: null,
127	      groups: [],        // one saved {stored, op} per open parenthesis
128	      error: false
129	    };
130	  }
131	
132	  function compute(a, op, b) {
133	    switch (op) {
134	      case '+': return a + b;
135	      case '-': return a - b;
136	      case '*': return a * b;
137	      case '/': return b === 0 ? NaN : a / b;
138	    }
139	    return b;
140	  }
141	
142	  function currentValue() {
143	    return state.typing ? parseFloat(state.entry) : state.value;
144	  }
145	
146	  // True when the display holds an entry: typed, or changed by ± or %.
147	  function hasEntry() {
148	    return state.typing || state.edited;
149	  }
150	
151	  // Presentation only: at most 10 significant digits, no trailing zeros,
152	  // exponential notation when |n| >= 1e10 or |n| < 1e-9. Never feed the
153	  // result back into a calculation.
154	  function format(n) {
155	    var m = Math.abs(n).toExponential(9).match(/^(\d)\.(\d+)e([+-]\d+)$/);
156	    var digits = m[1] + m[2];
157	    var exp = parseInt(m[3], 10);
158	    var sign = n < 0 ? '-' : '';
159	    var intPart, frac;
160	    if (Number(digits) === 0) return '0';
161	    if (exp >= 10 || exp < -9) {
162	      frac = m[2].replace(/0+$/, '');
163	      return sign + m[1] + (frac ? '.' + frac : '') + 'e' + (exp < 0 ? '-' : '+') + Math.abs(exp);
164	    }
165	    if (exp >= 0) {
166	      intPart = digits.slice(0, exp + 1);
167	      frac = digits.slice(exp + 1);
168	    } else {
169	      intPart = '0';
170	      frac = new Array(-exp).join('0') + digits;
171	    }
172	    frac = frac.replace(/0+$/, '');
173	    return sign + intPart + (frac ? '.' + frac : '');
174	  }
175	
176	  function render() {
177	    var text, value;
178	    if (state.error) {
179	      text = 'Error';
180	      value = 'NaN';
181	    } else {
182	      value = currentValue();
183	      text = state.typing ? state.entry : format(value);
184	      value = String(value);
185	    }
186	    display.textContent = text;
187	    display.setAttribute('data-value', value);
188	    display.setAttribute('data-error', state.error ? 'true' : 'false');
189	    display.setAttribute('data-open-groups', String(state.groups.length));
190	    groupsEl.textContent = new Array(state.groups.length + 1).join('(');
191	    display.classList.toggle('small', text.length > 9 && text.length <= 13);
192	    display.classList.toggle('tiny', text.length > 13);
193	    for (var i = 0; i < opButtons.length; i++) {
194	      var b = opButtons[i];
195	      b.classList.toggle('active', !hasEntry() && state.op === b.getAttribute('data-op'));
196	    }
197	  }
198	
199	  function setResult(n) {
200	    if (!isFinite(n)) {
201	      reset();
202	      state.error = true;
203	    } else {
204	      state.value = n;
205	    }
206	  }
207	
208	  function inputDigit(d) {
209	    if (!state.typing) {
210	      state.entry = d;
211	      state.typing = true;
212	      state.edited = false;
213	      if (state.op === null) state.lastOp = null;
214	    } else if (state.entry === '0' || state.entry === '-0') {
215	      state.entry = state.entry.slice(0, -1) + d;
216	    } else if (state.entry.replace(/[-.]/g, '').length < 16) {
217	      state.entry += d;
218	    }
219	  }
220	
221	  function inputDot() {
222	    if (!state.typing) {
223	      state.entry = '0.';
224	      state.typing = true;
225	      state.edited = false;
226	      if (state.op === null) state.lastOp = null;
227	    } else if (state.entry.indexOf('.') === -1) {
228	      state.entry += '.';
229	    }
230	  }
231	
232	  // ± and % act on the current entry at once. While typing, ± keeps the
233	  // entry editable. Otherwise the displayed value becomes the entry, so
234	  // after an operator it is the right operand: 5 + ± = is 0.
235	  function toggleSign() {
236	    if (state.typing) {
237	      state.entry = state.entry.charAt(0) === '-' ? state.entry.slice(1) : '-' + state.entry;
238	    } else if (state.value === 0) {
239	      // Start a negative entry: ± 5 is -5.
240	      state.entry = '-0';
241	      state.typing = true;
242	      state.edited = false;
243	      if (state.op === null) state.lastOp = null;
244	    } else {
245	      state.value = -state.value;
246	      state.edited = true;
247	    }
248	  }
249	
250	  function percent() {
251	    state.value = currentValue() / 100;
252	    state.typing = false;
253	    state.edited = true;
254	  }
255	
256	  // Immediate execution, strictly left to right, no operator precedence:
257	  // 2 + 3 × 4 = is 20. An operator key first finishes the operation already
258	  // waiting, so the display always shows a real running result.
259	  function inputOp(op) {
260	    var v = currentValue();
261	    if (state.op !== null && hasEntry()) {
262	      setResult(compute(state.stored, state.op, v));
263	      if (state.error) return;
264	    } else {
265	      state.value = v;
266	    }
267	    state.stored = state.value;
268	    state.op = op;
269	    state.typing = false;
270	    state.edited = false;
271	    state.lastOp = null;
272	  }
273	
274	  // Parentheses keep immediate execution. ( saves the waiting operation and
275	  // starts a fresh calculation, like a new number would. ) finishes that
276	  // calculation, restores the saved operation, and leaves the group result
277	  // as the entry: 2 + ( 3 × 4 ) = is 14. Groups nest.
278	  function openGroup() {
279	    state.groups.push({ stored: state.stored, op: state.op });
280	    state.stored = null;
281	    state.op = null;
282	    state.value = 0;
283	    state.typing = false;
284	    state.edited = false;
285	    state.lastOp = null;
286	  }
287	
288	  function closeGroup() {
289	    if (state.groups.length === 0) return;
290	    if (state.op !== null && hasEntry()) {
291	      setResult(compute(state.stored, state.op, currentValue()));
292	      if (state.error) return;
293	    } else {
294	      state.value = currentValue();
295	    }
296	    var saved = state.groups.pop();
297	    state.stored = saved.stored;
298	    state.op = saved.op;
299	    state.typing = false;
300	    state.edited = true;
301	    state.lastOp = null;
302	  }
303	
304	  function equals() {
305	    // = closes any groups still open.
306	    while (state.groups.length > 0 && !state.error) closeGroup();
307	    if (state.error) return;
308	    if (state.op !== null) {
309	      var b = hasEntry() ? currentValue() : state.stored;
310	      state.lastOp = state.op;
311	      state.lastOperand = b;
312	      setResult(compute(state.stored, state.op, b));
313	    } else if (state.lastOp !== null) {
314	      setResult(compute(currentValue(), state.lastOp, state.lastOperand));
315	    } else {
316	      state.value = currentValue();
317	    }
318	    if (state.error) return;
319	    state.op = null;
320	    state.stored = null;
321	    state.typing = false;
322	    state.edited = false;
323	  }
324	
325	  function handle(el) {
326	    var digit = el.getAttribute('data-digit');
327	    var op = el.getAttribute('data-op');
328	    var action = el.getAttribute('data-action');
329	    // In the error state only clear does anything.
330	    if (state.error && action !== 'clear') return;
331	    if (digit !== null) inputDigit(digit);
332	    else if (op !== null) inputOp(op);
333	    else if (action === 'dot') inputDot();
334	    else if (action === 'sign') toggleSign();
335	    else if (action === 'percent') percent();
336	    else if (action === 'lparen') openGroup();
337	    else if (action === 'rparen') closeGroup();
338	    else if (action === 'equals') equals();
339	    else if (action === 'clear') reset();
340	    render();
341	  }
342	
343	  document.querySelector('.keys').addEventListener('click', function (e) {
344	    var el = e.target.closest('button');
345	    if (el) handle(el);
346	  });
347	
348	  var keyMap = {
349	    '+': 'key-add', '-': 'key-sub', '*': 'key-mul', 'x': 'key-mul', '/': 'key-div',
350	    '.': 'key-dot', '%': 'key-percent', '(': 'key-lparen', ')': 'key-rparen', ',': 'key-dot', '=': 'key-equals', 'Enter': 'key-equals',
351	    'Escape': 'key-clear', 'c': 'key-clear', 'C': 'key-clear', 'Delete': 'key-clear'
352	  };
353	  document.addEventListener('keydown', function (e) {
354	    if (e.ctrlKey || e.metaKey || e.altKey) return;
355	    var id = /^[0-9]$/.test(e.key) ? 'key-' + e.key : keyMap[e.key];
356	    if (!id) return;
357	    e.preventDefault();
358	    handle(document.querySelector('[data-testid="' + id + '"]'));
359	  });
360	
361	  reset();
362	  render();
363	})();
364	</script>
365	</body>
366	</html>
